insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('planificar-las-compras-para-no-desperdiciar-alimentos','agricultura',array['negocios']::text[],'Planificar las compras para no desperdiciar alimentos','Crea una guía con pasos simples para planificar el menú y la lista de compras de una semana, comprar solo lo necesario y usar primero lo que se echa a perder más rápido.','Guía','2 semanas',14,array['Compras','Planificación']::text[],array['crear']::text[],'ficticios',NULL,'nutricion ingenieria alimentaria ingenieria ambiental educacion comunicaciones diseno trabajo social administracion planificacion. organizacion. estimacion de cantidades. diseno de plantillas. hoja de calculo. una plantilla. un editor de documentos.',$a45agr${"id": "planificar-las-compras-para-no-desperdiciar-alimentos", "area": "agricultura", "areas2": ["negocios"], "titulo": "Planificar las compras para no desperdiciar alimentos", "resumen": "Crea una guía con pasos simples para planificar el menú y la lista de compras de una semana, comprar solo lo necesario y usar primero lo que se echa a perder más rápido.", "tipo": "Guía", "tiempo": "2 semanas", "horas": 14, "etiquetas": ["Compras", "Planificación"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Nutrición", "Ingeniería Alimentaria", "Ingeniería Ambiental", "Educación", "Comunicaciones", "Diseño", "Trabajo Social", "Administración"], "problema": ["Se compran más alimentos de los que se consumen porque se improvisa, hay ofertas o no se recuerda lo que ya hay en casa. Muchos terminan en la basura antes de usarse.", "Planificar las compras ayuda a gastar menos y a desperdiciar menos."], "desarrollar": ["Con un caso de ejemplo de un hogar de tres personas, arma un menú semanal y la lista de compras que se necesita. Marca qué alimentos son más perecederos y deben consumirse primero y cuáles pueden esperar.", "Convierte el proceso en una guía de cinco o seis pasos con una plantilla de lista y un esquema de cómo ordenar la despensa. Prueba la guía con una semana real y anota qué ajustarías."], "ampliaciones": [{"titulo": "Plantilla descargable", "aporta": "diseña una plantilla imprimible."}, {"titulo": "Presupuesto", "aporta": "agrega una estimación del costo de la semana."}, {"titulo": "Sobras con propósito", "aporta": "añade ideas para usar las sobras en nuevas comidas."}], "objetivos": ["Armar un menú.", "Elaborar la lista de compras.", "Priorizar lo perecedero.", "Probar la guía."], "habilidades": ["Planificación.", "Organización.", "Estimación de cantidades.", "Diseño de plantillas."], "herramientas": ["Hoja de cálculo.", "Una plantilla.", "Un editor de documentos."], "lineamientos": ["Usa ejemplos genéricos y no recomiendes dietas ni cantidades personalizadas.", "No des consejos médicos ni nutricionales personalizados: si mencionas alimentación, apóyate en guías públicas y deriva a profesionales.", "Adapta la guía a quienes tengan restricciones alimentarias o presupuesto limitado."], "otroSector": "El mismo esquema de planificar y priorizar sirve para organizar inventarios y compras en cualquier pequeño negocio."}$a45agr$::jsonb,52),
('convertir-un-producto-agricola-en-otro-alimento','agricultura',array['negocios','industria']::text[],'Convertir un producto agrícola en otro alimento','Elige un producto agrícola que se pierde con facilidad o se vende barato y propón cómo transformarlo en otro alimento, como mermelada, harina o deshidratado, describiendo el proceso y a quién interesaría.','Plan','3 semanas',22,array['Transformación','Valor agregado']::text[],array['crear']::text[],'ficticios',NULL,'ingenieria alimentaria ingenieria agroindustrial nutricion ingenieria quimica quimica biologia diseno administracion analisis de procesos. estimacion de costos. pensamiento de negocio. comunicacion. fuentes confiables. hoja de calculo. un diagrama de flujo.',$a46agr${"id": "convertir-un-producto-agricola-en-otro-alimento", "area": "agricultura", "areas2": ["negocios", "industria"], "titulo": "Convertir un producto agrícola en otro alimento", "resumen": "Elige un producto agrícola que se pierde con facilidad o se vende barato y propón cómo transformarlo en otro alimento, como mermelada, harina o deshidratado, describiendo el proceso y a quién interesaría.", "tipo": "Plan", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Transformación", "Valor agregado"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Ingeniería Alimentaria", "Ingeniería Agroindustrial", "Nutrición", "Ingeniería Química", "Química", "Biología", "Diseño", "Administración"], "problema": ["Cuando un producto abunda o se maltrata, su precio baja y parte se pierde. Transformarlo puede darle más valor y mayor duración, pero requiere pensar el proceso, los costos y quiénes lo comprarían.", "Una propuesta bien pensada permite ver si la idea tiene sentido antes de invertir."], "desarrollar": ["Elige un producto agrícola y averigua sus características y cómo se transforma en otros alimentos en fuentes confiables. Describe en un diagrama los pasos del proceso desde la materia prima hasta el producto terminado.", "Estima con datos de ejemplo el costo, el rendimiento y el posible precio de venta, y piensa a quién podría interesarle. Aclara qué requisitos de salubridad y de registro habría que consultar, sin presentarlos como definitivos."], "ampliaciones": [{"titulo": "Dos alternativas", "aporta": "compara dos transformaciones posibles del mismo producto."}, {"titulo": "Marca y empaque", "aporta": "piensa en un nombre y un empaque."}, {"titulo": "Prueba de sabor", "aporta": "diseña una prueba voluntaria y anónima de aceptación."}], "objetivos": ["Elegir el producto.", "Diagramar el proceso.", "Estimar costos.", "Identificar el público."], "habilidades": ["Análisis de procesos.", "Estimación de costos.", "Pensamiento de negocio.", "Comunicación."], "herramientas": ["Fuentes confiables.", "Hoja de cálculo.", "Un diagrama de flujo."], "lineamientos": ["Aclara que es una propuesta académica y que cualquier producción real requiere permisos sanitarios y asesoría especializada.", "Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "Usa costos y precios de ejemplo, no cifras reales de negocios."], "otroSector": "El mismo ejercicio de dar valor agregado sirve para repensar cualquier materia prima o residuo como producto."}$a46agr$::jsonb,53),
('productos-que-no-se-ven-perfectos-pero-se-pueden-aprovechar','agricultura',array['negocios','sociedad']::text[],'Productos que no se ven perfectos pero se pueden aprovechar','Investiga qué pasa con frutas y verduras que no cumplen el aspecto que piden los mercados, y explora, con una encuesta breve y anónima, si las personas las comprarían a menor precio.','Investigación','3 semanas',20,array['Estándares estéticos','Aprovechamiento']::text[],array['investigar']::text[],'propios',NULL,'ingenieria agroindustrial economia administracion logistica estadistica sociologia marketing ingenieria industrial diseno de encuestas. analisis de respuestas. investigacion documental. redaccion. un formulario en linea. hoja de calculo. fuentes publicas.',$a47agr${"id": "productos-que-no-se-ven-perfectos-pero-se-pueden-aprovechar", "area": "agricultura", "areas2": ["negocios", "sociedad"], "titulo": "Productos que no se ven perfectos pero se pueden aprovechar", "resumen": "Investiga qué pasa con frutas y verduras que no cumplen el aspecto que piden los mercados, y explora, con una encuesta breve y anónima, si las personas las comprarían a menor precio.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Estándares estéticos", "Aprovechamiento"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Agroindustrial", "Economía", "Administración", "Logística", "Estadística", "Sociología", "Marketing", "Ingeniería Industrial"], "problema": ["Frutas y verduras con formas raras, manchas o tamaños irregulares muchas veces no llegan a venderse, aunque su sabor y su valor nutritivo son iguales. Se desechan por exigencias de apariencia que no tienen que ver con la calidad.", "Conocer qué piensan los consumidores ayuda a ver si hay espacio para aprovecharlos."], "desarrollar": ["Busca información pública sobre qué estándares de apariencia piden los mercados y cuánto se pierde por no cumplirlos. Diseña una encuesta corta y anónima de cinco preguntas sobre si comprarían productos imperfectos y a qué precio.", "Aplica la encuesta a un grupo pequeño con consentimiento, resume las respuestas y escribe una conclusión. Aclara que no representa a toda la población y propón dos ideas para aprovechar estos productos."], "ampliaciones": [{"titulo": "Fotos", "aporta": "muestra imágenes de productos imperfectos y observa reacciones."}, {"titulo": "Canal de venta", "aporta": "piensa en dónde se podrían vender con más facilidad."}, {"titulo": "Comparar edades", "aporta": "compara respuestas entre grupos de edad."}], "objetivos": ["Investigar los estándares.", "Diseñar la encuesta.", "Resumir respuestas.", "Proponer ideas de aprovechamiento."], "habilidades": ["Diseño de encuestas.", "Análisis de respuestas.", "Investigación documental.", "Redacción."], "herramientas": ["Un formulario en línea.", "Hoja de cálculo.", "Fuentes públicas."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "Haz la encuesta de forma voluntaria y anónima, sin pedir datos personales.", "Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir."], "otroSector": "El mismo análisis de apariencia frente a valor sirve para pensar en cómo se presentan y valoran productos de cualquier tipo."}$a47agr$::jsonb,54),
('un-empaque-para-distribuir-productos-agricolas','agricultura',array['industria','negocios']::text[],'Un empaque para distribuir productos agrícolas','Diseña un empaque pensado para llevar un producto agrícola frágil, como fresas o tomates, de la chacra al mercado, probando con un modelo qué tanto protege los golpes y la presión.','Prototipo','4 semanas',22,array['Empaques','Distribución']::text[],array['crear']::text[],'ficticios',NULL,'diseno ingenieria industrial ingenieria agroindustrial logistica ingenieria alimentaria ingenieria mecanica arquitectura marketing diseno de producto. prototipado. pruebas. documentacion tecnica. carton y materiales reutilizados. regla y tijeras. una camara.',$a48agr${"id": "un-empaque-para-distribuir-productos-agricolas", "area": "agricultura", "areas2": ["industria", "negocios"], "titulo": "Un empaque para distribuir productos agrícolas", "resumen": "Diseña un empaque pensado para llevar un producto agrícola frágil, como fresas o tomates, de la chacra al mercado, probando con un modelo qué tanto protege los golpes y la presión.", "tipo": "Prototipo", "tiempo": "4 semanas", "horas": 22, "etiquetas": ["Empaques", "Distribución"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Diseño", "Ingeniería Industrial", "Ingeniería Agroindustrial", "Logística", "Ingeniería Alimentaria", "Ingeniería Mecánica", "Arquitectura", "Marketing"], "problema": ["Muchos productos agrícolas se maltratan al apilarse o transportarse, y llegan golpeados al mercado. Los empaques pueden ayudar, pero deben ser económicos, fáciles de usar y resistentes.", "Diseñar y probar un empaque permite ver si realmente protege antes de producirlo."], "desarrollar": ["Elige un producto delicado y dibuja tres propuestas de empaque con materiales económicos, como cartón o fibras. Construye un modelo del más prometedor con materiales de casa.", "Prueba el modelo con un objeto de peso similar y con golpes suaves o apilado, y observa qué se deforma o falla. Ajusta el diseño y describe en una ficha sus medidas, materiales y los resultados de tus pruebas."], "ampliaciones": [{"titulo": "Costo por unidad", "aporta": "estima cuánto costaría el empaque por cada unidad."}, {"titulo": "Impacto ambiental", "aporta": "piensa en materiales reutilizables o reciclables."}, {"titulo": "Apilado", "aporta": "calcula cuántos empaques se pueden apilar con seguridad."}], "objetivos": ["Diseñar propuestas.", "Construir un modelo.", "Probar su resistencia.", "Documentar resultados."], "habilidades": ["Diseño de producto.", "Prototipado.", "Pruebas.", "Documentación técnica."], "herramientas": ["Cartón y materiales reutilizados.", "Regla y tijeras.", "Una cámara."], "lineamientos": ["Usa objetos de prueba y no alimentos que vayas a vender o consumir después.", "Aclara que el prototipo es un modelo académico y no un empaque certificado.", "Prefiere materiales reutilizables o reciclables."], "otroSector": "El mismo diseño y prueba de empaques sirve para proteger cualquier producto frágil durante su traslado."}$a48agr$::jsonb,55),
('que-dificultades-tienen-los-pequenos-productores-para-llevar-sus','agricultura',array['negocios','sociedad']::text[],'¿Qué dificultades tienen los pequeños productores para llevar sus productos al mercado?','Investiga qué obstáculos enfrentan los pequeños agricultores para vender sus productos, como el transporte, la información de precios o los intermediarios, usando informes públicos y casos documentados.','Investigación','3 semanas',22,array['Pequeños productores','Acceso a mercados']::text[],array['investigar']::text[],'publicos',NULL,'ingenieria agroindustrial economia administracion logistica estadistica sociologia marketing ingenieria industrial investigacion documental. clasificacion. analisis de problemas. redaccion. informes publicos. hoja de calculo. un editor de documentos.',$a49agr${"id": "que-dificultades-tienen-los-pequenos-productores-para-llevar-sus", "area": "agricultura", "areas2": ["negocios", "sociedad"], "titulo": "¿Qué dificultades tienen los pequeños productores para llevar sus productos al mercado?", "resumen": "Investiga qué obstáculos enfrentan los pequeños agricultores para vender sus productos, como el transporte, la información de precios o los intermediarios, usando informes públicos y casos documentados.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Pequeños productores", "Acceso a mercados"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Agroindustrial", "Economía", "Administración", "Logística", "Estadística", "Sociología", "Marketing", "Ingeniería Industrial"], "problema": ["Producir no basta: hay que llevar el producto al mercado a tiempo y a un buen precio. Muchos pequeños productores enfrentan caminos difíciles, falta de transporte, poca información de precios y dependencia de intermediarios.", "Conocer estos obstáculos ayuda a pensar en soluciones realistas y a entender por qué lo que pagamos no siempre llega a quien cultiva."], "desarrollar": ["Busca estudios, informes y notas de instituciones agrarias sobre las dificultades de comercialización de pequeños productores. Clasifica los obstáculos en transporte, información, financiamiento, almacenamiento y relación con intermediarios.", "Para cada categoría, describe un ejemplo y una posible mejora que haya funcionado en otro lugar. Resume tus hallazgos en un informe de dos páginas con una tabla de obstáculos y soluciones."], "ampliaciones": [{"titulo": "Caso regional", "aporta": "profundiza en una zona o cultivo concreto."}, {"titulo": "Mapa de actores", "aporta": "dibuja quiénes participan en la venta de un producto."}, {"titulo": "Propuesta", "aporta": "plantea una solución sencilla para un obstáculo específico."}], "objetivos": ["Reunir información confiable.", "Clasificar obstáculos.", "Identificar mejoras posibles.", "Redactar un informe."], "habilidades": ["Investigación documental.", "Clasificación.", "Análisis de problemas.", "Redacción."], "herramientas": ["Informes públicos.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "Si conversas con productores o vendedores, hazlo con su permiso, sin publicar nombres ni datos de contacto; si prefieren no participar, usa casos inventados.", "Describe las dificultades como condiciones que enfrentan los productores y no como fallas suyas."], "otroSector": "El mismo análisis de obstáculos para llegar al cliente sirve para cualquier emprendimiento pequeño."}$a49agr$::jsonb,56),
('que-influye-en-el-precio-de-un-alimento-del-productor-al-mercado','agricultura',array['negocios']::text[],'¿Qué influye en el precio de un alimento, del productor al mercado?','Analiza cómo cambia el precio de un alimento desde que sale de la chacra hasta que se vende al público, con datos públicos, e identifica qué factores explican la diferencia.','Análisis','3 semanas',22,array['Precios','Cadena de valor']::text[],array['investigar']::text[],'publicos',NULL,'ingenieria agroindustrial economia administracion logistica estadistica sociologia marketing ingenieria industrial analisis de precios. visualizacion. pensamiento critico. comunicacion. datos publicos de precios. hoja de calculo. graficos.',$a50agr${"id": "que-influye-en-el-precio-de-un-alimento-del-productor-al-mercado", "area": "agricultura", "areas2": ["negocios"], "titulo": "¿Qué influye en el precio de un alimento, del productor al mercado?", "resumen": "Analiza cómo cambia el precio de un alimento desde que sale de la chacra hasta que se vende al público, con datos públicos, e identifica qué factores explican la diferencia.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Precios", "Cadena de valor"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Agroindustrial", "Economía", "Administración", "Logística", "Estadística", "Sociología", "Marketing", "Ingeniería Industrial"], "problema": ["El precio que recibe un agricultor suele ser muy distinto al que paga el consumidor. En el camino hay transporte, almacenamiento, pérdidas y márgenes de cada actor, pero casi nunca se ve cómo se reparte el precio.", "Analizarlo permite entender de dónde viene lo que pagamos y evita culpar sin datos a un solo actor."], "desarrollar": ["Elige un alimento y reúne precios públicos en chacra, en mercado mayorista y en venta minorista, en una misma fecha o periodo. Calcula la diferencia entre cada etapa y la proporción del precio final que corresponde a cada una.", "Haz una gráfica de cascada o de barras y escribe una explicación de qué factores pueden explicar cada diferencia, como transporte, pérdidas, almacenamiento o margen comercial. Señala las limitaciones de los datos."], "ampliaciones": [{"titulo": "Dos productos", "aporta": "compara la diferencia de precios de un producto fresco y uno procesado."}, {"titulo": "Evolución", "aporta": "observa cómo cambia la diferencia durante el año."}, {"titulo": "Escenario", "aporta": "simula qué pasaría si se eliminara un intermediario."}], "objetivos": ["Reunir precios por etapa.", "Calcular diferencias.", "Visualizar la distribución.", "Explicar los factores."], "habilidades": ["Análisis de precios.", "Visualización.", "Pensamiento crítico.", "Comunicación."], "herramientas": ["Datos públicos de precios.", "Hoja de cálculo.", "Gráficos."], "lineamientos": ["Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "No acuses a ningún grupo de abusar: describe factores y deja que los datos hablen, señalando sus límites.", "Aclara que son precios de referencia y no un análisis económico completo."], "otroSector": "El mismo análisis de cómo se forma un precio sirve para estudiar cualquier producto que pasa por varias manos."}$a50agr$::jsonb,57),
('conectar-a-pequenos-productores-con-consumidores-locales','agricultura',array['negocios','sociedad']::text[],'Conectar a pequeños productores con consumidores locales','Diseña un modelo sencillo para que un grupo de consumidores compre directamente a pequeños productores: cómo se organizan los pedidos, quién entrega, cómo se paga y cómo se reparte el riesgo.','Plan','4 semanas',24,array['Venta directa','Compras locales']::text[],array['crear','resolver']::text[],'ficticios',NULL,'ingenieria agroindustrial economia administracion logistica estadistica sociologia marketing ingenieria industrial diseno de modelos de negocio. planificacion. estimacion. comunicacion. hoja de calculo. un diagrama de flujo. un documento de acuerdo.',$a51agr${"id": "conectar-a-pequenos-productores-con-consumidores-locales", "area": "agricultura", "areas2": ["negocios", "sociedad"], "titulo": "Conectar a pequeños productores con consumidores locales", "resumen": "Diseña un modelo sencillo para que un grupo de consumidores compre directamente a pequeños productores: cómo se organizan los pedidos, quién entrega, cómo se paga y cómo se reparte el riesgo.", "tipo": "Plan", "tiempo": "4 semanas", "horas": 24, "etiquetas": ["Venta directa", "Compras locales"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Ingeniería Agroindustrial", "Economía", "Administración", "Logística", "Estadística", "Sociología", "Marketing", "Ingeniería Industrial"], "problema": ["Productores y consumidores a veces están cerca pero no se conectan: el productor vende a intermediarios y el consumidor compra en tiendas. Los modelos de compra directa pueden beneficiar a ambos, pero requieren organización y confianza.", "Diseñar bien las reglas antes de empezar evita malentendidos y abandonos."], "desarrollar": ["Con un caso imaginario de cinco productores y veinte familias, define qué productos se ofrecen, cada cuánto se hacen pedidos y cómo se recibe y se entrega. Decide cómo se fijan los precios y cómo se maneja lo que no se vende.", "Dibuja el flujo del modelo, redacta las reglas del grupo y calcula, con datos de ejemplo, qué ganaría cada parte. Anticipa tres posibles problemas, como retrasos o diferencias de calidad, y cómo resolverlos."], "ampliaciones": [{"titulo": "Pedidos en línea", "aporta": "piensa en cómo usar un formulario o chat para recibir pedidos."}, {"titulo": "Rutas de entrega", "aporta": "planifica una ruta simple de entrega."}, {"titulo": "Comunicación", "aporta": "diseña un mensaje semanal con lo que hay disponible."}], "objetivos": ["Definir el funcionamiento.", "Diagramar el flujo.", "Calcular beneficios.", "Anticipar problemas."], "habilidades": ["Diseño de modelos de negocio.", "Planificación.", "Estimación.", "Comunicación."], "herramientas": ["Hoja de cálculo.", "Un diagrama de flujo.", "Un documento de acuerdo."], "lineamientos": ["Usa un caso inventado: no incluyas productores ni familias reales sin su permiso.", "Si conversas con productores o vendedores, hazlo con su permiso, sin publicar nombres ni datos de contacto; si prefieren no participar, usa casos inventados.", "Aclara que cualquier venta real requiere cumplir normas sanitarias y comerciales."], "otroSector": "El mismo modelo de conectar oferta y demanda de forma directa sirve para cualquier venta entre vecinos o comunidades."}$a51agr$::jsonb,58),
('como-vender-productos-agricolas-que-tienen-poca-demanda','agricultura',array['negocios']::text[],'Cómo vender productos agrícolas que tienen poca demanda','Elige un producto agrícola poco conocido o poco comprado y piensa cómo darlo a conocer: a quién le interesaría, cómo presentarlo, dónde venderlo y qué mensaje usar.','Plan','3 semanas',20,array['Poca demanda','Comercialización']::text[],array['crear','resolver']::text[],'ficticios',NULL,'ingenieria agroindustrial economia administracion logistica estadistica sociologia marketing ingenieria industrial analisis de mercado simple. comunicacion. creatividad. planificacion. fuentes publicas. un editor de diseno. hoja de calculo.',$a52agr${"id": "como-vender-productos-agricolas-que-tienen-poca-demanda", "area": "agricultura", "areas2": ["negocios"], "titulo": "Cómo vender productos agrícolas que tienen poca demanda", "resumen": "Elige un producto agrícola poco conocido o poco comprado y piensa cómo darlo a conocer: a quién le interesaría, cómo presentarlo, dónde venderlo y qué mensaje usar.", "tipo": "Plan", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Poca demanda", "Comercialización"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Ingeniería Agroindustrial", "Economía", "Administración", "Logística", "Estadística", "Sociología", "Marketing", "Ingeniería Industrial"], "problema": ["Hay productos nutritivos y de buena calidad que casi no se venden porque la gente no los conoce o no sabe cómo usarlos. El productor sigue cultivándolos pero no encuentra compradores.", "Pensar en el público, el mensaje y el lugar de venta puede convertir un producto desconocido en una opción atractiva."], "desarrollar": ["Elige un producto poco consumido de tu zona y averigua sus características, sus usos y por qué se compra poco. Define a qué tipo de comprador podría interesarle y qué necesita saber para animarse a probarlo.", "Elabora un plan simple de tres acciones, como una receta fácil, una presentación en una feria o un mensaje en redes. Estima cómo medirías si funciona y qué ajustarías."], "ampliaciones": [{"titulo": "Mensaje y nombre", "aporta": "prueba dos formas de presentar el mismo producto."}, {"titulo": "Alianzas", "aporta": "piensa con qué restaurantes o tiendas podría colaborar."}, {"titulo": "Degustación", "aporta": "diseña una actividad de degustación voluntaria y segura."}], "objetivos": ["Conocer el producto y su público.", "Diseñar un mensaje.", "Elegir acciones.", "Definir cómo medir resultados."], "habilidades": ["Análisis de mercado simple.", "Comunicación.", "Creatividad.", "Planificación."], "herramientas": ["Fuentes públicas.", "Un editor de diseño.", "Hoja de cálculo."], "lineamientos": ["No des consejos médicos ni nutricionales personalizados: si mencionas alimentación, apóyate en guías públicas y deriva a profesionales.", "No prometas beneficios para la salud que no estén respaldados por fuentes oficiales.", "Usa un caso de ejemplo y respeta a las comunidades que cultivan el producto."], "otroSector": "El mismo plan de dar a conocer un producto sirve para cualquier emprendimiento que necesita encontrar sus primeros clientes."}$a52agr$::jsonb,59),
('catalogo-de-variedades-tradicionales-de-una-region','agricultura',array['sociedad']::text[],'Catálogo de variedades tradicionales de una región','Elabora un catálogo ilustrado de las variedades tradicionales de un cultivo de tu región, como papas o maíces, con sus nombres, características y usos, para valorar y dar a conocer esa diversidad.','Guía','4 semanas',22,array['Variedades tradicionales','Patrimonio agrícola']::text[],array['crear','investigar']::text[],'publicos',NULL,'antropologia historia agronomia nutricion comunicaciones biologia sociologia diseno grafico investigacion documental. sintesis. diseno de informacion. redaccion. fuentes publicas. un editor de diseno. un mapa sencillo.',$a53agr${"id": "catalogo-de-variedades-tradicionales-de-una-region", "area": "agricultura", "areas2": ["sociedad"], "titulo": "Catálogo de variedades tradicionales de una región", "resumen": "Elabora un catálogo ilustrado de las variedades tradicionales de un cultivo de tu región, como papas o maíces, con sus nombres, características y usos, para valorar y dar a conocer esa diversidad.", "tipo": "Guía", "tiempo": "4 semanas", "horas": 22, "etiquetas": ["Variedades tradicionales", "Patrimonio agrícola"], "intencion": ["crear", "investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Antropología", "Historia", "Agronomía", "Nutrición", "Comunicaciones", "Biología", "Sociología", "Diseño Gráfico"], "problema": ["En muchas regiones se han cultivado por generaciones variedades propias de un mismo alimento, con colores, sabores y usos distintos. Muchas se están perdiendo porque se prefieren unas pocas variedades comerciales.", "Un catálogo ayuda a valorar esa diversidad y a que más personas la conozcan."], "desarrollar": ["Elige un cultivo con variedades tradicionales en tu región y reúne información pública de instituciones agrarias y de investigación sobre sus nombres, características y usos. Prefiere fuentes que citen a las comunidades que las conservan.", "Elabora una ficha por variedad con su nombre, su descripción, dónde se cultiva y cómo se usa, y arma un catálogo con un diseño uniforme. Incluye las fuentes y reconoce a las comunidades que las han conservado."], "ampliaciones": [{"titulo": "Mapa de variedades", "aporta": "ubica en un mapa dónde se cultiva cada variedad."}, {"titulo": "Recetas", "aporta": "agrega un uso culinario por variedad."}, {"titulo": "Versión digital", "aporta": "convierte el catálogo en una página web."}], "objetivos": ["Reunir información confiable.", "Elaborar fichas.", "Diseñar el catálogo.", "Citar fuentes y comunidades."], "habilidades": ["Investigación documental.", "Síntesis.", "Diseño de información.", "Redacción."], "herramientas": ["Fuentes públicas.", "Un editor de diseño.", "Un mapa sencillo."], "lineamientos": ["Documenta saberes tradicionales con permiso y cita siempre a quien te los comparte; no los presentes como propios ni como recetas con fines médicos.", "Indica de dónde salen los datos, con la fecha de consulta, y aclara que son referenciales y no sirven para decidir por tu cuenta qué sembrar o cuánto invertir.", "Usa imágenes propias o libres de derechos y evita reproducir fotografías ajenas sin permiso."], "otroSector": "El mismo catálogo de variedades sirve para registrar y valorar la diversidad de cualquier producto tradicional."}$a53agr$::jsonb,60),
('guia-visual-para-reconocer-cuando-madura-una-fruta-o-verdura','agricultura',array['salud']::text[],'Guía visual para reconocer cuándo madura una fruta o verdura','Fotografía y observa frutas y verduras a lo largo de su maduración y arma una guía con fotos y señales de color, firmeza y aroma para saber cuándo están en su mejor momento.','Guía','3 semanas',16,array['Maduración','Guía visual']::text[],array['crear']::text[],'propios',NULL,'nutricion ingenieria alimentaria ingenieria ambiental educacion comunicaciones diseno trabajo social administracion observacion. fotografia. diseno de informacion. comunicacion visual. camara del celular. frutas y verduras. un editor de diseno.',$a54agr${"id": "guia-visual-para-reconocer-cuando-madura-una-fruta-o-verdura", "area": "agricultura", "areas2": ["salud"], "titulo": "Guía visual para reconocer cuándo madura una fruta o verdura", "resumen": "Fotografía y observa frutas y verduras a lo largo de su maduración y arma una guía con fotos y señales de color, firmeza y aroma para saber cuándo están en su mejor momento.", "tipo": "Guía", "tiempo": "3 semanas", "horas": 16, "etiquetas": ["Maduración", "Guía visual"], "intencion": ["crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Nutrición", "Ingeniería Alimentaria", "Ingeniería Ambiental", "Educación", "Comunicaciones", "Diseño", "Trabajo Social", "Administración"], "problema": ["Se compran frutas que no maduran nunca o que ya están pasadas. Reconocer el punto justo de cada una depende del color, de la firmeza y del aroma, y no todas se comportan igual.", "Una guía visual ayuda a comprar y consumir en el momento adecuado y a reducir pérdidas."], "desarrollar": ["Elige entre cuatro y seis frutas o verduras comunes y compra algunas en estado verde o poco maduro. Fotografíalas cada día o cada dos días y anota el color, la firmeza al tacto suave y el aroma hasta que estén pasadas.", "Selecciona las fotos que mejor muestran las etapas y arma una guía con tres o cuatro etapas para cada fruta, y una nota sobre cuándo conviene consumirla. Pide a alguien que use la guía y comenta si se entiende."], "ampliaciones": [{"titulo": "Con apoyo de escala", "aporta": "crea una escala de color para cada fruta."}, {"titulo": "Consejos de compra", "aporta": "agrega cómo elegir en el mercado."}, {"titulo": "Cómo acelerar o frenar", "aporta": "prueba cómo cambia la maduración según dónde guardes la fruta."}], "objetivos": ["Registrar la maduración.", "Seleccionar fotos clave.", "Elaborar la guía.", "Probarla con otra persona."], "habilidades": ["Observación.", "Fotografía.", "Diseño de información.", "Comunicación visual."], "herramientas": ["Cámara del celular.", "Frutas y verduras.", "Un editor de diseño."], "lineamientos": ["No pruebes ni consumas alimentos que parezcan echados a perder; el objetivo es observar, no arriesgarse.", "No des consejos médicos ni nutricionales personalizados: si mencionas alimentación, apóyate en guías públicas y deriva a profesionales.", "No pruebes frutas en mal estado para comprobar su maduración; guíate por lo que puedas ver y oler."], "otroSector": "El mismo ejercicio de reconocer etapas visuales sirve para guías de control de calidad en cualquier proceso."}$a54agr$::jsonb,61),
('plantas-amigas-cultivar-juntas-ayuda','agricultura',array['ambiente']::text[],'Plantas amigas: ¿cultivar juntas ayuda?','Cultiva una planta sola y la misma planta junto a otra que dicen que le ayuda, como albahaca con tomate, y compara cómo crecen para ver si la asociación realmente hace diferencia.','Análisis','6 semanas',24,array['Cultivos asociados','Experimento']::text[],array['investigar']::text[],'propios',NULL,'agronomia biologia ingenieria ambiental educacion nutricion ingenieria agroindustrial diseno arquitectura diseno de experimentos. observacion. analisis de datos. pensamiento critico. macetas. regla. hoja de calculo.',$a55agr${"id": "plantas-amigas-cultivar-juntas-ayuda", "area": "agricultura", "areas2": ["ambiente"], "titulo": "Plantas amigas: ¿cultivar juntas ayuda?", "resumen": "Cultiva una planta sola y la misma planta junto a otra que dicen que le ayuda, como albahaca con tomate, y compara cómo crecen para ver si la asociación realmente hace diferencia.", "tipo": "Análisis", "tiempo": "6 semanas", "horas": 24, "etiquetas": ["Cultivos asociados", "Experimento"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Agronomía", "Biología", "Ingeniería Ambiental", "Educación", "Nutrición", "Ingeniería Agroindustrial", "Diseño", "Arquitectura"], "problema": ["Se dice que algunas plantas crecen mejor juntas porque espantan plagas o se ayudan con la sombra y los nutrientes. Muchas de estas recomendaciones se repiten sin comprobarse, y algunas no tienen respaldo.", "Probar la asociación en pequeño permite ver qué ocurre y distinguir entre tradición y evidencia."], "desarrollar": ["Elige una pareja de plantas comestibles que se recomiende asociar y siembra tres macetas: una con la planta principal sola, otra con la acompañante sola y otra con las dos juntas. Mantén igual el sustrato, la luz y el riego.", "Durante varias semanas mide la altura, cuenta las hojas y anota si aparecen plagas o señales de enfermedad. Compara los resultados y concluye con cautela si la asociación ayudó, siendo claro en que es una prueba pequeña."], "ampliaciones": [{"titulo": "Otra pareja", "aporta": "repite con otra combinación recomendada."}, {"titulo": "Distancia", "aporta": "compara qué pasa si las plantas están más cerca o más lejos."}, {"titulo": "Revisión de fuentes", "aporta": "contrasta lo que observaste con lo que dicen las guías."}], "objetivos": ["Seleccionar una asociación.", "Preparar un experimento comparable.", "Medir el crecimiento.", "Concluir con cautela."], "habilidades": ["Diseño de experimentos.", "Observación.", "Análisis de datos.", "Pensamiento crítico."], "herramientas": ["Macetas.", "Regla.", "Hoja de cálculo."], "lineamientos": ["Es un experimento pequeño y personal: pocas plantas o pocas muestras durante pocas semanas. No pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir en tu caso.", "No uses pesticidas ni productos químicos en tu experimento; si una planta se enferma, anótalo como parte del registro.", "No tomes un resultado como regla: una sola prueba no basta para decir que una asociación siempre funciona."], "otroSector": "El mismo método de comparar solo contra combinado sirve para evaluar cualquier trabajo en equipo o mezcla de ingredientes."}$a55agr$::jsonb,62)
